<script setup lang="ts">import { onMounted, computed } from 'vue'; import { useRouter } from 'vue-router'; import { useOrderStore } from '../../stores/orders'; import { useUserCenterStore } from '../../stores/userCenter'; const router=useRouter(); const orders=useOrderStore(); const user=useUserCenterStore(); const pending=computed(()=>orders.orders.filter(o=>o.status==='PENDING_PAYMENT').length); const shipped=computed(()=>orders.orders.filter(o=>o.status==='SHIPPED'||o.status==='PENDING_SHIPMENT').length); onMounted(async()=>{await orders.loadMyOrders(); await user.loadFavorites()}); function label(s:string){return ({PENDING_PAYMENT:'待付款',PENDING_SHIPMENT:'待发货',SHIPPED:'待收货',COMPLETED:'已完成',CANCELLED:'已取消'} as Record<string,string>)[s]||s}</script>
<template><div class="user-heading"><div><p class="eyebrow">USER CENTER</p><h1>欢迎回来，{{ user.profile?.nickname || '农友' }}</h1></div></div><div class="stat-grid"><button class="stat-card orange" @click="router.push({ name:'user-orders', query:{status:'wait'} })"><strong>{{ pending }}</strong><span>待付款</span></button><button class="stat-card blue" @click="router.push({ name:'user-orders', query:{status:'ship'} })"><strong>{{ shipped }}</strong><span>待收货</span></button><button class="stat-card" @click="router.push({ name:'user-orders' })"><strong>{{ orders.orders.length }}</strong><span>全部订单</span></button><button class="stat-card pink" @click="router.push({ name:'user-favorites' })"><strong>{{ user.favorites.length }}</strong><span>收藏商品</span></button></div><section class="user-panel"><div class="panel-heading"><h2>最近订单</h2><RouterLink :to="{name:'user-orders'}">查看全部</RouterLink></div><div v-for="order in orders.orders.slice(0,3)" :key="order.id" class="recent-order"><img :src="order.items[0]?.productImageUrl" alt="商品"/><div><strong>{{ order.items[0]?.productName || '农产品订单' }}</strong><small>订单号 {{ order.orderNo }}</small></div><b>¥{{ order.totalAmount.toFixed(2) }}</b><span class="status-chip">{{ label(order.status) }}</span></div></section></template>
